## TODO (for Copilot or maintainer)
Create an icons utility that loads and base64 encodes at build/startup:

```typescript
import * as fs from 'fs';
import * as path from 'path';

const ICONS_DIR = path.join(__dirname, 'assets', 'icons');

export function loadIcon(name: string): string {
  const data = fs.readFileSync(path.join(ICONS_DIR, `${name}.png`));
  return `data:image/png;base64,${data.toString('base64')}`;
}

export const icons = {
  wavingHand: loadIcon('waving_hand'),
  sunBehindCloud: loadIcon('sun_behind_cloud'),
  robot: loadIcon('robot'),
  hourglass: loadIcon('hourglass'),
  package: loadIcon('package'),
  abacus: loadIcon('abacus'),
};
```

Then use these icons in tool definitions.

